 31	function readiness(): Readonly<{ readonly missing: readonly string[]; readonly ready: boolean }> {
 32		const missing = REQUIRED_NODE_OWNERS.filter((owner) => {
 33			const filename = path.resolve(REPOSITORY_ROOT, owner);
 34			if (!fs.existsSync(filename)) return true;
 35			const source = fs.readFileSync(filename, "utf8");
 36			return owner.endsWith("issuance-maintenance.ts")
 37				? !source.includes("resolveNodeDurableIssuancePruningMaintenance")
 38				: !source.includes("pruned_through_author_sequence");
 39		});
 40		return Object.freeze({ missing: Object.freeze(missing), ready: missing.length === 0 });
 41	}
 42	
 43	function primary(label: string): string {
 44		const directory = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), `d109b-node-${label}-`));
 45		directories.push(directory);
 46		return path.join(directory, "primary.sqlite");
 47	}
 48	
 49	function derived(primaryFilename: string): string {
 50		return `${primaryFilename}${DATABASE_SUFFIX}`;
 51	}
 52	
 53	function scalar(database: DatabaseSync, sql: string): unknown {
 54		const statement = database.prepare(sql);
 55		statement.setReadBigInts(false);
 56		const row = statement.get();
 57		return row === undefined ? undefined : Object.values(row)[0];
 58	}
 59	
 60	function catalog(database: DatabaseSync): readonly Record<string, unknown>[] {
 61		const statement = database.prepare("SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY type,name");
 62		statement.setReadBigInts(false);
 63		return statement.all();
 64	}
