 66	function createV1Authority(primaryFilename: string, rows = 1): void {
 67		const database = new DatabaseSync(derived(primaryFilename));
 68		try {
 69			database.exec("PRAGMA page_size=4096");
 70			database.prepare("PRAGMA journal_mode=WAL").get();
 71			database.exec("BEGIN IMMEDIATE");
 72			database.exec(PHASE_2L_C_V1_LINEAGES_DDL);
 73			database.exec(PHASE_2L_C_DDL.issued_records);
 74			database.exec(PHASE_2L_C_DDL.issuance_outbox);
 75			if (rows > 0) {
 76				database
 77					.prepare("INSERT INTO lineages(object_id,author,next,exhausted) VALUES(?,?,?,?)")
 78					.run(D109B_SCOPE.objectId, D109B_SCOPE.author, rows, 0);
 79				const issued = database.prepare(
 80					"INSERT INTO issued_records(object_id,author,author_sequence,canonical_preimage,digest,signature) VALUES(?,?,?,?,?,?)"
 81				);
 82				const outbox = database.prepare(
 83					"INSERT INTO issuance_outbox(object_id,author,author_sequence,digest,publish_state) VALUES(?,?,?,?,?)"
 84				);
 85				for (let authorSequence = 0; authorSequence < rows; authorSequence += 1) {
 86					const commit = d109bCommit(D109B_SCOPE, authorSequence, 4);
 87					issued.run(
 88						D109B_SCOPE.objectId,
 89						D109B_SCOPE.author,
 90						authorSequence,
 91						commit.envelope.canonicalPreimageBytes,
 92						commit.envelope.digest,
 93						commit.envelope.signature
 94					);
 95					outbox.run(D109B_SCOPE.objectId, D109B_SCOPE.author, authorSequence, commit.envelope.digest, "published");
 96				}
 97			}
 98			database.exec("PRAGMA user_version=1");
 99			database.exec("COMMIT");
100		} finally {
101			database.close();
102		}
103	}
