105	async function childAdmission(childFixture: string, primaryFilename: string): Promise<void> {
106		const children = [0, 1].map(() =>
107			spawn(process.execPath, [childFixture, primaryFilename, "plain-barrier"], {
108				stdio: ["ignore", "ignore", "pipe", "ipc"],
109			})
110		);
111		await Promise.all(
112			children.map(
113				(child) =>
114					new Promise<void>((resolvePromise, reject) => {
115						const timeout = setTimeout(() => reject(new Error("D109B_ADMISSION_READY_TIMEOUT")), 10_000);
116						child.once("error", reject);
117						child.on("message", (message: { readonly kind?: string; readonly message?: string }) => {
118							if (message.kind === "ready") {
119								clearTimeout(timeout);
120								resolvePromise();
121							}
122							if (message.kind === "child-error") reject(new Error(message.message));
123						});
124					})
125			)
126		);
127		for (const child of children) child.send("start");
128		await Promise.all(
129			children.map(
130				(child) =>
131					new Promise<void>((resolvePromise, reject) => {
132						let admitted = false;
133						let stderr = "";
134						const timeout = setTimeout(() => {
135							child.kill("SIGKILL");
136							reject(new Error(`D109B_ADMISSION_TIMEOUT:${stderr}`));
137						}, 15_000);
138						child.stderr?.setEncoding("utf8");
139						child.stderr?.on("data", (value: string) => (stderr += value));
140						child.once("error", reject);
141						child.on("message", (message: { readonly kind?: string; readonly message?: string }) => {
142							if (message.kind === "admitted") admitted = true;
143							if (message.kind === "child-error") reject(new Error(message.message));
144						});
145						child.once("exit", (code) => {
146							clearTimeout(timeout);
147							if (code === 0 && admitted) resolvePromise();
148							else reject(new Error(`D109B_ADMISSION_EXIT:${String(code)}:${stderr}`));
149						});
150					})
151			)
152		);
153	}
