280	async function mutateNative(databaseName: string, mutant: string): Promise<void> {
281		const database = await openNative(databaseName);
282		try {
283			const transaction = database.transaction(["issuedRecords", "issuanceOutbox"], "readwrite");
284			const issued = transaction.objectStore("issuedRecords");
285			const outbox = transaction.objectStore("issuanceOutbox");
286			const sequence = mutant === "epoch-regression" || mutant === "sequence-gap" ? 1 : 0;
287			const key = [SCOPE.objectId, SCOPE.author, sequence];
288			if (mutant === "issued-only") await requestValue(outbox.delete(key));
289			else if (mutant === "outbox-only") await requestValue(issued.delete(key));
290			else if (mutant === "sequence-gap") {
291				await requestValue(issued.delete(key));
292				await requestValue(outbox.delete(key));
293			} else if (mutant === "digest-mismatch") {
294				const row = (await requestValue(outbox.get(key))) as Record<string, unknown>;
295				await requestValue(outbox.put({ ...row, digest: Uint8Array.of(255) }));
296			} else {
297				const row = (await requestValue(issued.get(key))) as Record<string, unknown>;
298				let canonicalPreimageBytes: Uint8Array;
299				if (mutant === "canonical-malformed") canonicalPreimageBytes = Uint8Array.of(0);
300				else {
301					canonicalPreimageBytes = encodeCanonical({
302						...SCOPE,
303						author: mutant === "scope-wrong" ? "z".repeat(64) : SCOPE.author,
304						authorSequence: mutant === "ordinal-wrong" ? sequence + 1 : sequence,
305						epoch: mutant === "epoch-wrong" ? 5 : mutant === "epoch-regression" ? 3 : 4,
306						kind: mutant === "vertex-kind-wrong" ? "not-a-vertex" : "drp-vertex",
307						protocolMajor: mutant === "protocol-major-wrong" ? 2 : 3,
308					});
309				}
310				await requestValue(issued.put({ ...row, canonicalPreimageBytes }));
311			}
312			await transactionDone(transaction);
313		} finally {
314			database.close();
315		}
316	}
