318	async function runNativeMutants(prefix: string): Promise<readonly Readonly<Record<string, unknown>>[]> {
319		const mutants = [
320			"canonical-malformed",
321			"vertex-kind-wrong",
322			"protocol-major-wrong",
323			"scope-wrong",
324			"ordinal-wrong",
325			"epoch-wrong",
326			"issued-only",
327			"outbox-only",
328			"digest-mismatch",
329			"sequence-gap",
330			"epoch-regression",
331		] as const;
332		const results: Readonly<Record<string, unknown>>[] = [];
333		for (const mutant of mutants) {
334			const databaseName = `${prefix}-${mutant}`;
335			const seeded = await createBrowserDurableIssuanceStore({ primaryDatabaseName: databaseName });
336			for (let index = 0; index < 3; index += 1) await issue(seeded, SCOPE, 4);
337			await seeded.close();
338			await mutateNative(databaseName, mutant);
339			const store = await createBrowserDurableIssuanceStore({ primaryDatabaseName: databaseName });
340			const owner = resolveBrowserDurableIssuancePruningMaintenance(store);
341			if (owner === undefined) throw new TypeError("D109B_BROWSER_MAINTENANCE_MISSING");
342			const state = await owner.inspectPruningState(SCOPE);
343			const code = await capturedCode(() =>
344				owner.prunePublishedPrefix({
345					closedEpoch: 4,
346					commitQcRef: { byteLength: 32, digest: "e".repeat(64) },
347					expectedLineage: state.lineage,
348					expectedPrunedThroughAuthorSequence: state.prunedThroughAuthorSequence,
349					scope: SCOPE,
350					snapshotManifestDigest: "f".repeat(64),
351					throughAuthorSequence: 2,
352				})
353			);
354			await store.close();
355			const database = await openNative(databaseName);
356			try {
357				const transaction = database.transaction(["issuedRecords", "issuanceOutbox", "lineages"], "readonly");
358				const [issuedCount, outboxCount, lineage] = await Promise.all([
359					requestValue(transaction.objectStore("issuedRecords").count()),
360					requestValue(transaction.objectStore("issuanceOutbox").count()),
361					requestValue(transaction.objectStore("lineages").get([SCOPE.objectId, SCOPE.author])),
362				]);
363				await transactionDone(transaction);
364				results.push(
365					Object.freeze({
366						code,
367						issuedCount,
368						mutant,
369						outboxCount,
370						watermark: (lineage as Record<string, unknown>).prunedThroughAuthorSequence ?? null,
371					})
372				);
373			} finally {
374				database.close();
375			}
376		}
377		return Object.freeze(results);
378	}
